import React from 'react';
import { motion } from 'framer-motion';
import { Code2, Cpu, Globe, Zap } from 'lucide-react';

const techs = [
    { name: "React 19", icon: <Globe size={16} />, detail: "Modern UI" },
    { name: "Framer Motion", icon: <Zap size={16} />, detail: "Animations" },
    { name: "Lucide Icons", icon: <Code2 size={16} />, detail: "SVG Set" },
    { name: "LocalStorage", icon: <Cpu size={16} />, detail: "Persistence" },
];

function TechStack() {
    return (
        <section className="tech-stack">
            <h4 className="tech-title">System Architecture</h4>
            <div className="tech-grid">
                {techs.map((tech, i) => (
                    <motion.div
                        key={tech.name}
                        initial={{ opacity: 0, scale: 0.9 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        viewport={{ once: true }}
                        transition={{ delay: i * 0.1 }}
                        className="tech-card"
                    >
                        <div className="tech-icon-wrapper">{tech.icon}</div>
                        <div className="tech-info">
                            <span className="tech-name">{tech.name}</span>
                            <span className="tech-detail">{tech.detail}</span>
                        </div>
                    </motion.div>
                ))}
            </div>
        </section>
    );
}

export default TechStack;
